const s = $input.first().json || {};

function fail(detail) {
  return [{ json: { ...s, _2e_fail: { code: 'INTERNAL_CONTRACT_ERROR', detail } } }];
}

if (s._2e_fail) return [{ json: s }];

if (!s.account_company || typeof s.account_company !== 'object' || Array.isArray(s.account_company)) {
  return fail('account_company missing at live HR discovery provider entry');
}

const orgId = s.account_company.provider_refs && s.account_company.provider_refs.apollo_organization_id;
if (typeof orgId !== 'string' || !orgId.trim()) {
  return fail('account_company.provider_refs.apollo_organization_id missing at live HR discovery provider entry');
}

const limit = s._2e && s._2e.DISCOVERY_FETCH_LIMIT;
if (!Number.isInteger(limit) || limit <= 0) {
  return fail('_2e.DISCOVERY_FETCH_LIMIT missing or invalid at live HR discovery provider entry');
}
if (limit !== 15) {
  return fail('live HR discovery expects frozen DISCOVERY_FETCH_LIMIT=15');
}

const titles = ["recruiting operations", "recruitment operations", "talent acquisition operations", "ta operations", "recruiting program", "recruitment program", "talent acquisition", "talent sourcing", "talent partner", "talent recruiter", "talent recruiting", "sourcer", "recruiter", "recruiting", "recruitment", "staffing", "headhunter", "headhunting", "people operations", "people ops", "people partner", "people and culture", "employee experience", "talent management", "talent development", "people analytics", "chief people officer", "chief talent officer", "human resources", "human resource", "human resources business partner", "hr business partner", "employee relations", "hr", "hrbp", "hris"];

const params = [];
params.push('organization_ids[]=' + encodeURIComponent(orgId.trim()));
for (const t of titles) params.push('person_titles[]=' + encodeURIComponent(t));
params.push('include_similar_titles=true');
params.push('page=1');
params.push('per_page=' + encodeURIComponent(String(limit)));

const url =
  'https://api.apollo.io/api/v1/mixed_people/api_search?' +
  params.join('&');

const clean = { ...s };
delete clean._2e_provider_raw;
delete clean._2e_transport;

return [{
  json: {
    ...clean,
    _disc_live: {
      provider: 'apollo',
      operation: 'hr_people_discovery',
      endpoint_identity: 'https://api.apollo.io/api/v1/mixed_people/api_search',
      organization_id: orgId.trim(),
      person_titles: titles,
      include_similar_titles: true,
      page: 1,
      per_page: limit,
      url,
      attempt: 1,
      attempt_result: null,
      retry_delay_ms: null
    }
  }
}];

const s = $input.first().json || {};
if (s._2e_fail) return [{ json: s }];

const d = s._disc_live || {};
if (d.operation !== 'hr_people_discovery') {
  return [{ json: { ...s, _2e_fail: { code:'INTERNAL_CONTRACT_ERROR', detail:'invalid discovery operation before HTTP call' } } }];
}
if (typeof d.url !== 'string' || !d.url.startsWith('https://api.apollo.io/api/v1/mixed_people/api_search?')) {
  return [{ json: { ...s, _2e_fail: { code:'INTERNAL_CONTRACT_ERROR', detail:'invalid Apollo discovery URL before HTTP call' } } }];
}
if (!Number.isInteger(d.attempt) || d.attempt < 1 || d.attempt > 3) {
  return [{ json: { ...s, _2e_fail: { code:'INTERNAL_CONTRACT_ERROR', detail:'invalid discovery attempt counter before HTTP call' } } }];
}
return [{ json: s }];

const incoming = $input.first().json || {};
let s;
try { s = $('2E Discovery - Prepare HTTP Attempt').item.json || {}; }
catch (e) { s = {}; }

if (s._2e_fail) return [{ json: s }];

const d = s._disc_live || {};
const attempt = Number(d.attempt || 1);

function errText(x) {
  if (x === null || x === undefined) return '';
  if (typeof x === 'string') return x;
  try { return JSON.stringify(x); } catch (e) { return String(x); }
}

function statusCodeOf(o) {
  const vals = [
    o.statusCode,
    o.status_code,
    o.http_status,
    o.error && o.error.statusCode,
    o.error && o.error.status
  ];
  for (const v of vals) {
    const n = Number(v);
    if (Number.isInteger(n) && n >= 100 && n <= 599) return n;
  }
  const m = errText(o.error || o.message || '').match(/\b([1-5]\d{2})\b/);
  return m ? Number(m[1]) : null;
}

const http = statusCodeOf(incoming);
const nodeError = incoming.error ? errText(incoming.error).toLowerCase() : '';

let retry = false;
let transientExhausted = false;
let envelopeValid = false;
let people = null;
let transportClass = null;
let errorCode = null;

if (incoming.error && http === null) {
  const cls = /timeout|timed out|etimedout/.test(nodeError) ? 'TIMEOUT' : 'NETWORK_ERROR';
  retry = attempt < 3;
  transientExhausted = attempt >= 3;
  transportClass = transientExhausted ? 'TRANSIENT_EXHAUSTED' : cls;
  errorCode = cls;
}
else if (
  http === 408 ||
  http === 425 ||
  http === 429 ||
  (http !== null && http >= 500 && http <= 599)
) {
  retry = attempt < 3;
  transientExhausted = attempt >= 3;
  transportClass = transientExhausted ? 'TRANSIENT_EXHAUSTED' : ('HTTP_TRANSIENT_' + http);
  errorCode = 'HTTP_' + http;
}
else if (http === 401 || http === 403) {
  transportClass = 'HTTP_' + http;
  errorCode = 'HTTP_' + http;
}
else if (http !== null && (http < 200 || http >= 300)) {
  transportClass = 'HTTP_' + http;
  errorCode = 'HTTP_' + http;
}
else {
  const body = incoming.body !== undefined ? incoming.body : incoming;
  if (body && typeof body === 'object' && !Array.isArray(body) && Array.isArray(body.people)) {
    envelopeValid = true;
    people = body.people;
    transportClass = 'SUCCESS';
    errorCode = null;
  } else {
    transportClass = 'INVALID_SHARED_ENVELOPE';
    errorCode = 'MALFORMED_TOP_LEVEL_COLLECTION';
  }
}

const retryDelayMs = retry ? (attempt === 1 ? 2000 : 5000) : null;

return [{
  json: {
    ...s,
    _disc_live: {
      ...d,
      attempt_result: {
        retry,
        transient_exhausted: transientExhausted,
        envelope_valid: envelopeValid,
        people,
        http_status: http,
        transport_class: transportClass,
        error_code: errorCode
      },
      retry_delay_ms: retryDelayMs
    }
  }
}];

const s = $input.first().json || {};
if (s._2e_fail) return [{ json:s }];

const d = s._disc_live || {};
const ar = d.attempt_result || {};

if (ar.retry !== true) {
  return [{ json:{ ...s, _2e_fail:{ code:'INTERNAL_CONTRACT_ERROR', detail:'discovery retry advance reached without retry=true' } } }];
}

const nextAttempt = Number(d.attempt || 1) + 1;
if (nextAttempt > 3) {
  return [{ json:{ ...s, _2e_fail:{ code:'INTERNAL_CONTRACT_ERROR', detail:'discovery retry exceeded 3 attempts' } } }];
}

return [{
  json: {
    ...s,
    _disc_live: {
      ...d,
      attempt: nextAttempt,
      attempt_result: null
    }
  }
}];

const s = $input.first().json || {};
if (s._2e_fail) return [{ json:s }];

const d = s._disc_live || {};
const ar = d.attempt_result || {};
const now = new Date().toISOString();

if (ar.retry === true) {
  return [{
    json: {
      ...s,
      _2e_fail: {
        code: 'INTERNAL_CONTRACT_ERROR',
        detail: 'discovery finalize reached while retry still required'
      }
    }
  }];
}

let raw;

if (ar.envelope_valid === true && Array.isArray(ar.people)) {
  const candidates = ar.people.map((p, idx) => {
    const person = (p && typeof p === 'object' && !Array.isArray(p)) ? p : {};
    return {
      person_id:
        typeof person.id === 'string' && person.id.trim()
          ? person.id.trim()
          : null,
      name: null,
      linkedin_url: null,
      title:
        typeof person.title === 'string' && person.title.trim()
          ? person.title.trim()
          : null,
      organization_name:
        person.organization &&
        typeof person.organization.name === 'string' &&
        person.organization.name.trim()
          ? person.organization.name.trim()
          : null,
      provider_rank: idx + 1
    };
  });

  raw = {
    provider: 'apollo',
    envelope_valid: true,
    candidates
  };
} else {
  raw = {
    provider: 'apollo',
    envelope_valid: false,
    candidates: []
  };
}

const out = {
  ...s,
  _2e_provider_raw: raw,
  _2e_transport: {
    attempts: Number(d.attempt || 1),
    http_status:
      Number.isInteger(ar.http_status)
        ? ar.http_status
        : null,
    error_code: ar.error_code || null,
    transport_class: ar.transport_class || null,
    transient_exhausted: ar.transient_exhausted === true
  },
  _2e_now: now
};

delete out._disc_live;

return [{ json: out }];
